def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1, 2, 3, 4, 5, 6, 7]), fmt([1, 4, 1, 3, 8]), fmt([2, 4, 6]), fmt([0]), fmt([1]), fmt([10**6 - 1]),
             fmt([1] * 15 + [3] + [0, 2]), fmt([1, 1, 2]), fmt([3, 3, 5, 7, 9, 0]), fmt([999999, 999999, 1])]
    for n in (2, 3, 5, 8, 12, 20):
        for _ in range(3):
            hi = rng.choice([5, 30, 1000])
            tests.append(fmt([rng.randint(0, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(0, 10**6) for _ in range(N)]))
    tests.append(fmt([10**6 - 1] * N))
    tests.append(fmt([2 * rng.randint(0, 5 * 10**5) for _ in range(N)]))
    tests.append(fmt([rng.choice([1, 1, 1, 2]) for _ in range(N)]))
    return tests

